def img(key,alt,cls='',eager=False,sizes='(max-width: 900px) 100vw, 50vw'):
 files=list((OUT/'assets'/'img').glob(key+'-*.webp'))
 widths=sorted(int(f.stem.rsplit('-',1)[1]) for f in files)
 if not widths: raise ValueError('Missing image '+key)
 width,height=DIMENSIONS[key+'-'+str(widths[-1])]
 srcs=', '.join(f'/assets/img/{key}-{w}.webp {w}w' for w in widths)
 return f'<img class="{cls}" src="/assets/img/{key}-{widths[-1]}.webp" srcset="{srcs}" sizes="{sizes}" alt="{escape(alt)}" width="{width}" height="{height}" '+('fetchpriority="high" loading="eager"' if eager else 'loading="lazy"')+' decoding="async">'

