def label(text):return f'<p class="eyebrow">{text}</p>'
def heading(kicker,title,desc=''):return f'<div class="page-heading wrap">{label(kicker)}<h1>{title}</h1>{f"<p class=lead>{desc}</p>" if desc else ""}</div>'

