SD=json.dumps(SCHEMA,separators=(',',':'),ensure_ascii=False)
SD_HASH=base64.b64encode(hashlib.sha256(SD.encode()).digest()).decode()
CSP=f"default-src 'none'; script-src 'self' 'sha256-{SD_HASH}'; style-src 'self'; img-src 'self'; font-src 'self'; connect-src 'none'; manifest-src 'none'; frame-src 'none'; form-action 'none'; base-uri 'none'; object-src 'none'; upgrade-insecure-requests"
