def page(path,title,body,desc='',active='',closing=True,noindex=False):
 directory=OUT/path.strip('/');directory.mkdir(parents=True,exist_ok=True)
 url=ORIGIN+('/'+path.strip('/')+'/' if path else '/')
 full=f'{title} · BG. Event Management'
 og=ORIGIN+'/assets/img/lsg10rqvt2qktddcjxqo-1116.webp'
 robots='noindex,follow' if noindex else 'index,follow,max-image-preview:large'
 canon='' if noindex else f'<link rel="canonical" href="{url}">'
 head=(f'<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#7a1712">'
  f'<meta http-equiv="Content-Security-Policy" content="{CSP}"><title>{escape(full)}</title><meta name="description" content="{escape(desc)}"><meta name="robots" content="{robots}">{canon}'
  f'<meta property="og:site_name" content="BG. Event Management"><meta property="og:locale" content="en_IN"><meta property="og:title" content="{escape(full)}"><meta property="og:description" content="{escape(desc)}"><meta property="og:type" content="website"><meta property="og:url" content="{url}">'
  f'<meta property="og:image" content="{og}"><meta property="og:image:width" content="1116"><meta property="og:image:height" content="644"><meta property="og:image:alt" content="Gold traditional stage with elaborate floral décor from the BG. Event Management portfolio">'
  f'<meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{escape(full)}"><meta name="twitter:description" content="{escape(desc)}"><meta name="twitter:image" content="{og}">'
  '<link rel="icon" href="/favicon.ico" sizes="48x48"><link rel="icon" type="image/png" sizes="32x32" href="/assets/img/favicon-32.png"><link rel="apple-touch-icon" href="/assets/img/apple-touch-icon.png">'
  '<link rel="preload" href="/assets/fonts/serif.woff2" as="font" type="font/woff2" crossorigin><link rel="preload" href="/assets/fonts/sans.woff2" as="font" type="font/woff2" crossorigin><link rel="preload" href="/assets/fonts/serif-italic.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="'+CSS_URL+'"><script src="'+JS_URL+'" defer></script>'
  f'<script type="application/ld+json">{SD}</script>')
 html='<!DOCTYPE html><html lang="en"><head>'+head+'</head><body>'+header(active)+'<main id="main">'+body+'</main>'+footer()+'</body></html>'
