about=heading('Our story','Care at the heart<br><em>of every occasion.</em>','We’re BG. Event Management. A planning and coordination team bringing people together across Tamil Nadu.')+'<section class="wrap about-split"><div class="portrait">'+img('egvepq4urmzfwd3dbaoh','G. Balaji, Director of BG. Event Management',eager=True,sizes='(max-width: 640px) 360px, 40vw')+'<div>'+label('The person behind the planning')+'<p class="person-name">G. Balaji</p><p>Director · BG. Event Management</p></div></div><div>'+label('Based in Madurai. Here for your moments.')+'<h2>A personal approach.<br><em>A dependable team.</em></h2><p>Every gathering has its own purpose, people and personality. Our job is to understand yours, then make the planning feel clear and manageable.</p><p>We combine creative thinking with practical coordination: schedules, suppliers, venue requirements, production and the finishing touches. From intimate family celebrations to larger public occasions, we bring the same attention and care.</p><p>Our promise is simple: listen carefully, communicate clearly and deliver with care.</p>'+textlink('Meet us over a conversation','/contact/')+'</div></section><section class="section values-section"><div class="wrap">'+label('What guides us')+'<h2>Good events begin<br><em>with good principles.</em></h2><div class="steps">'+''.join('<article><h3>'+t+'</h3><p>'+d+'</p></article>' for t,d in [('People first.','We plan around your priorities, preferences and the people you’re bringing together.'),('Clarity throughout.','A practical plan, clear communication and coordination across the agreed event details.'),('Care in the details.','The big picture matters. So do the small touches that make the occasion feel personal.')])+'</div></div></section><section class="section wrap"><div class="section-top"><div>'+label('Together, behind the scenes')+'<h2>The work behind<br><em>the wonderful.</em></h2></div><p class="section-aside">A flexible team and event partners, working together from the first planning call to the final send-off.</p></div><div class="team-images">'+img('un4glxbhugvpxc05kody','BG. team coordinating event sound',sizes='(max-width: 900px) 50vw, 600px')+img('ebvnbfxhorwrskzbsw30','Event hosts in front of a BG. Event Management backdrop',sizes='(max-width: 900px) 50vw, 600px')+'</div></section>'
page('about','Our story',about,'Meet BG. Event Management, directed by G. Balaji. Thoughtful event planning and coordination from Thirumangalam, Madurai, across Tamil Nadu.',active='about')

page('reviews','Kind words from our clients',heading('The memories stay with people','The little words<br><em>that mean a lot.</em>','Feedback shared by families and clients on the BG. Event Management website.')+'<section class="wrap section reviews-page">'+reviewcards()+'<p class="image-provenance">Short excerpts from reviews published on bgeventmanagement.in/reviews. No aggregate rating is claimed.</p></section><section class="review-photo wrap">'+img('hrkaec8ijviutyganrhp','Fairy-garden birthday celebration',sizes='(max-width: 1300px) 96vw, 1240px')+'</section>','Read client feedback on BG. Event Management weddings, birthdays and event coordination.',active='reviews')

