# keep the Content-Security-Policy response header in vercel.json in step with the page hash
vj=ROOT/'vercel.json'
if vj.exists():
 cfg=json.loads(vj.read_text())
 for rule in cfg.get('headers',[]):
  if rule['source']=='/(.*)':
   rule['headers']=[h for h in rule['headers'] if h['key']!='Content-Security-Policy']+[{'key':'Content-Security-Policy','value':HEADER_CSP}]
 vj.write_text(json.dumps(cfg,indent=2,ensure_ascii=False)+'\n')
